import type { ComponentProps, ReactNode } from 'react'

import { cn } from '@/lib/utils'

export type AppIconProps = ComponentProps<'svg'>

function AppIcon({
  viewBox,
  children,
  className,
  ...props
}: AppIconProps & { viewBox: string; children: ReactNode }) {
  return (
    <svg
      data-slot="app-icon"
      viewBox={viewBox}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden
      focusable="false"
      className={cn('size-5 shrink-0', className)}
      {...props}
    >
      {children}
    </svg>
  )
}

